import{_ as o,o as t,c as r,a1 as n}from"./chunks/framework.DdbKPUhY.js";const u=JSON.parse('{"title":"Protocol Upgrade Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/protocol-upgrade.md","filePath":"spec/protocol-upgrade.md"}'),i={name:"spec/protocol-upgrade.md"};function c(a,e,s,l,d,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="protocol-upgrade-spec" tabindex="-1">Protocol Upgrade Spec <a class="header-anchor" href="#protocol-upgrade-spec" aria-label="Permalink to &quot;Protocol Upgrade Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Protocol Upgrade module provides a framework for upgrading HTTP connections to custom protocols (such as IPPS, gRPC-Web, WebSocket, etc.). It manages a registry of protocol detectors and handlers, handles connection ownership transfer to external libraries, and supports lifecycle callbacks for cleanup after upgrade. The module is the core mechanism behind the HTTP Upgrade and WebSocket handshake paths.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-server-register-protocol-upgrade" tabindex="-1">uvhttp_server_register_protocol_upgrade <a class="header-anchor" href="#uvhttp-server-register-protocol-upgrade" aria-label="Permalink to &quot;uvhttp_server_register_protocol_upgrade&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_register_protocol_upgrade(uvhttp_server_t* server, const char* protocol_name, const char* upgrade_header, uvhttp_protocol_detector_t detector, uvhttp_protocol_upgrade_handler_t handler, void* user_data)</code></li><li><strong>Purpose</strong>: Register a protocol upgrade handler for a server</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>protocol_name</code>, <code>detector</code>, and <code>handler</code> must be non-NULL. <code>protocol_name</code> must be &lt; 32 characters. <code>upgrade_header</code> (if provided) must be &lt; 64 characters.</li><li><strong>Postconditions</strong>: On success, the protocol is registered in the server&#39;s protocol registry (inserted at head for LIFO detection order). The protocol name and upgrade header are normalized to lowercase. <code>server-&gt;protocol_registry</code> is created if it did not exist.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code>, <code>protocol_name</code>, <code>detector</code>, or <code>handler</code> is NULL; protocol name or upgrade header exceeds max length; protocol count exceeds 10 (max)</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure for registry or protocol info</li><li><code>UVHTTP_ERROR_ALREADY_EXISTS</code>: a protocol with the same name is already registered</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe. Must be called before the server starts listening.</li><li><strong>Detection order</strong>: Newly registered protocols are checked first (LIFO due to head insertion).</li></ul><h3 id="uvhttp-server-unregister-protocol-upgrade" tabindex="-1">uvhttp_server_unregister_protocol_upgrade <a class="header-anchor" href="#uvhttp-server-unregister-protocol-upgrade" aria-label="Permalink to &quot;uvhttp_server_unregister_protocol_upgrade&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_unregister_protocol_upgrade(uvhttp_server_t* server, const char* protocol_name)</code></li><li><strong>Purpose</strong>: Unregister a protocol upgrade handler</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>protocol_name</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, the protocol is removed from the registry and its memory is freed. The protocol count is decremented.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> or <code>protocol_name</code> is NULL</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: protocol is not registered, or no registry exists</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe. Must not be called while connections are being upgraded.</li></ul><h3 id="uvhttp-protocol-find" tabindex="-1">uvhttp_protocol_find <a class="header-anchor" href="#uvhttp-protocol-find" aria-label="Permalink to &quot;uvhttp_protocol_find&quot;">​</a></h3><ul><li><strong>Signature</strong> (internal): The framework&#39;s detection logic iterates the protocol registry linked list. For each registered protocol, the <code>Upgrade</code> and <code>Connection</code> headers are pre-fetched from the request. If the protocol has an <code>upgrade_header</code> string set, a fast lowercase comparison is performed first. If that matches, or if no upgrade_header was set, the detector function is called.</li><li><strong>Purpose</strong>: Find a matching protocol for an incoming HTTP upgrade request</li><li><strong>Preconditions</strong>: The server must have a non-NULL protocol registry. The request must be a valid HTTP request with Upgrade and Connection headers.</li><li><strong>Postconditions</strong>: Returns the first matching protocol info, or NULL if no match is found.</li><li><strong>Thread safety</strong>: Not thread-safe. Must be called from the request handler thread.</li></ul><h3 id="uvhttp-connection-transfer-ownership" tabindex="-1">uvhttp_connection_transfer_ownership <a class="header-anchor" href="#uvhttp-connection-transfer-ownership" aria-label="Permalink to &quot;uvhttp_connection_transfer_ownership&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_transfer_ownership(uvhttp_connection_t* conn, uvhttp_connection_ownership_callback_t callback, void* user_data)</code></li><li><strong>Purpose</strong>: Transfer ownership of a TCP connection to an external library</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid and in <code>UVHTTP_CONN_STATE_HTTP_PROCESSING</code> state. <code>callback</code> must be non-NULL. The connection must not already be upgraded.</li><li><strong>Postconditions</strong>: The connection&#39;s HTTP reading is stopped, the timeout timer is stopped, the file descriptor is obtained, and the connection state is set to <code>UVHTTP_CONN_STATE_PROTOCOL_UPGRADED</code>. The callback is invoked with the TCP handle, fd, and user data.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>conn</code> or <code>callback</code> is NULL</li><li><code>UVHTTP_ERROR_CONNECTION_INIT</code>: connection is in an invalid state, or already upgraded, or fd is invalid</li><li><code>UVHTTP_ERROR_IO_ERROR</code>: failed to get file descriptor</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe. Must be called from the event loop thread.</li></ul><h3 id="uvhttp-connection-set-lifecycle" tabindex="-1">uvhttp_connection_set_lifecycle <a class="header-anchor" href="#uvhttp-connection-set-lifecycle" aria-label="Permalink to &quot;uvhttp_connection_set_lifecycle&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_set_lifecycle(uvhttp_connection_t* conn, uvhttp_connection_lifecycle_t* lifecycle)</code></li><li><strong>Purpose</strong>: Set a lifecycle callback for when the connection is closed (used for cleanup by external libraries)</li><li><strong>Preconditions</strong>: <code>conn</code> and <code>lifecycle</code> must be non-NULL. <code>lifecycle-&gt;on_close</code> must be set.</li><li><strong>Postconditions</strong>: The lifecycle callback structure is stored in the connection. The callback will be invoked when the connection is closed.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>conn</code> or <code>lifecycle</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure for lifecycle structure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-get-fd" tabindex="-1">uvhttp_connection_get_fd <a class="header-anchor" href="#uvhttp-connection-get-fd" aria-label="Permalink to &quot;uvhttp_connection_get_fd&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_get_fd(uvhttp_connection_t* conn, int* fd)</code></li><li><strong>Purpose</strong>: Get the file descriptor of a connection</li><li><strong>Preconditions</strong>: <code>conn</code> and <code>fd</code> must be non-NULL.</li><li><strong>Postconditions</strong>: <code>*fd</code> is set to the socket file descriptor.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>conn</code> or <code>fd</code> is NULL</li><li><code>UVHTTP_ERROR_IO_ERROR</code>: <code>uv_fileno</code> failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-get-peer-address" tabindex="-1">uvhttp_connection_get_peer_address <a class="header-anchor" href="#uvhttp-connection-get-peer-address" aria-label="Permalink to &quot;uvhttp_connection_get_peer_address&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_get_peer_address(uvhttp_connection_t* conn, struct sockaddr_storage* addr, socklen_t* addr_len)</code></li><li><strong>Purpose</strong>: Get the peer address of a connection</li><li><strong>Preconditions</strong>: <code>conn</code>, <code>addr</code>, and <code>addr_len</code> must be non-NULL.</li><li><strong>Postconditions</strong>: <code>*addr</code> is filled with the peer&#39;s socket address. <code>*addr_len</code> is set to the actual address length.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM**: </code>conn<code>, </code>addr<code>, or </code>addr_len` is NULL</li><li><code>UVHTTP_ERROR_IO_ERROR</code>: <code>uv_tcp_getpeername</code> failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="type-definitions" tabindex="-1">Type Definitions <a class="header-anchor" href="#type-definitions" aria-label="Permalink to &quot;Type Definitions&quot;">​</a></h2><h3 id="uvhttp-protocol-detector-t" tabindex="-1">uvhttp_protocol_detector_t <a class="header-anchor" href="#uvhttp-protocol-detector-t" aria-label="Permalink to &quot;uvhttp_protocol_detector_t&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int (*detector)(uvhttp_request_t* request, char* protocol_name, size_t protocol_name_len, const char* upgrade_header, const char* connection_header)</code></li><li><strong>Purpose</strong>: Detect whether an HTTP request matches a specific protocol. Pre-fetched headers (<code>Upgrade</code>, <code>Connection</code>) are passed to avoid repeated lookups.</li><li><strong>Preconditions</strong>: <code>request</code> must be valid. <code>protocol_name</code> must be a buffer of at least <code>protocol_name_len</code> bytes.</li><li><strong>Postconditions</strong>: Returns 1 if the protocol is detected, 0 otherwise. On detection, <code>protocol_name</code> may be filled with the protocol name.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-protocol-upgrade-handler-t" tabindex="-1">uvhttp_protocol_upgrade_handler_t <a class="header-anchor" href="#uvhttp-protocol-upgrade-handler-t" aria-label="Permalink to &quot;uvhttp_protocol_upgrade_handler_t&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t (*handler)(uvhttp_connection_t* conn, const char* protocol_name, void* user_data)</code></li><li><strong>Purpose</strong>: Handle the protocol upgrade logic after detection</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid and in HTTP processing state. <code>protocol_name</code> must be non-NULL.</li><li><strong>Postconditions</strong>: The handler performs the upgrade (e.g., sends 101 Switching Protocols, transfers connection ownership).</li><li><strong>Thread safety</strong>: Not thread-safe. Must be called from the event loop thread.</li></ul><h3 id="uvhttp-connection-ownership-callback-t" tabindex="-1">uvhttp_connection_ownership_callback_t <a class="header-anchor" href="#uvhttp-connection-ownership-callback-t" aria-label="Permalink to &quot;uvhttp_connection_ownership_callback_t&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void (*callback)(uv_tcp_t* tcp_handle, int fd, void* user_data)</code></li><li><strong>Purpose</strong>: Receive ownership of a TCP connection for an external library</li><li><strong>Preconditions</strong>: <code>tcp_handle</code> is valid and the connection is stopped. <code>fd</code> is a valid socket descriptor.</li><li><strong>Postconditions</strong>: The external library now owns the connection and is responsible for all I/O and cleanup.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="websocket-upgrade-path" tabindex="-1">WebSocket Upgrade Path <a class="header-anchor" href="#websocket-upgrade-path" aria-label="Permalink to &quot;WebSocket Upgrade Path&quot;">​</a></h2><p>The WebSocket protocol follows the standard HTTP upgrade mechanism:</p><ol><li>The client sends an HTTP GET request with headers: <code>Upgrade: websocket</code>, <code>Connection: Upgrade</code>, <code>Sec-WebSocket-Key: &lt;base64-key&gt;</code>, <code>Sec-WebSocket-Version: 13</code>.</li><li>The server&#39;s protocol detector identifies the WebSocket upgrade request.</li><li>The WebSocket upgrade handler validates the <code>Sec-WebSocket-Key</code> and generates the <code>Sec-WebSocket-Accept</code> response.</li><li>The server responds with HTTP 101 Switching Protocols.</li><li>The server transfers connection ownership via <code>uvhttp_connection_transfer_ownership</code>.</li><li>The WebSocket module takes over the raw socket for frame-level communication.</li></ol><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Protocol registration</strong>: Protocols are stored in a linked list with LIFO detection order. Newly registered protocols are checked first.</p></li><li><p><strong>Fast matching</strong>: If an <code>upgrade_header</code> string is provided during registration, the framework performs a fast lowercase comparison against the <code>Upgrade</code> header before calling the detector function.</p></li><li><p><strong>Protocol name normalization</strong>: Protocol names and upgrade header values are normalized to lowercase during registration. Detection comparisons are case-insensitive.</p></li><li><p><strong>Maximum protocols</strong>: At most 10 protocols can be registered. Attempting to register more returns <code>UVHTTP_ERROR_INVALID_PARAM</code>.</p></li><li><p><strong>Duplicate prevention</strong>: Registering a protocol with the same name as an existing one returns <code>UVHTTP_ERROR_ALREADY_EXISTS</code>.</p></li><li><p><strong>Connection state validation</strong>: Ownership transfer requires the connection to be in <code>UVHTTP_CONN_STATE_HTTP_PROCESSING</code> state. The state transitions to <code>UVHTTP_CONN_STATE_PROTOCOL_UPGRADED</code> after transfer.</p></li><li><p><strong>Ownership transfer sequence</strong>: Stop HTTP reading, stop timeout timer, get file descriptor, validate fd, mark connection as upgraded, call the callback.</p></li><li><p><strong>Lifecycle callbacks</strong>: After ownership transfer, an external library can set a lifecycle callback to be notified when the connection is closed, allowing cleanup of external resources.</p></li><li><p><strong>Detector function contract</strong>: The detector function receives pre-fetched header values to avoid redundant header lookups. It should only return 1 if it is certain the protocol matches.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>Protocol registration: O(1) (head insertion into linked list)</li><li>Protocol unregistration: O(n) where n is the number of registered protocols</li><li>Protocol detection: O(n) worst-case (linear scan of registry), with fast string comparison optimization</li><li>Ownership transfer: O(1) (stop handles, get fd, set state, invoke callback)</li><li>Memory: ~128 bytes per registered protocol info</li><li>Protocol count limit: 10 (to bound detection time)</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Protocol registration and unregistration</li><li>Duplicate protocol registration returns UVHTTP_ERROR_ALREADY_EXISTS</li><li>Protocol detection with exact match, case-insensitive match</li><li>Protocol detection with fast matching (upgrade_header provided)</li><li>Protocol detection when no upgrade_header is provided (detector-only)</li><li>Protocol not found returns NULL</li><li>Unregister a non-existent protocol returns UVHTTP_ERROR_NOT_FOUND</li><li>Maximum protocol count enforcement (10)</li><li>Protocol name too long (&gt; 32 chars) rejected</li><li>Upgrade header too long (&gt; 64 chars) rejected</li><li>Connection ownership transfer (valid state, invalid state, already upgraded)</li><li>Connection lifecycle callback invocation</li><li>Connection get_fd and get_peer_address</li><li>NULL parameter handling for all public functions</li><li>Memory cleanup (no leaks on free, registry cleanup on server free)</li><li>WebSocket upgrade path (handshake, ownership transfer, lifecycle)</li></ul>',34)])])}const g=o(i,[["render",c]]);export{u as __pageData,g as default};
